DELETE FROM AUD_BUSINESS_RULES_RESULTS WHERE BUSINESS_RULE_RESULT_ID IN (
SELECT t.BUSINESS_RULE_RESULT_ID AS row_id FROM AUD_BUSINESS_RULES_RESULTS t WHERE (EXISTS (SELECT 1 FROM AUD_PIPELINES_RUN_LOG r JOIN CFG_PIPELINES p ON p.PIPELINE_ID=r.PIPELINE_ID WHERE p.PROJECT_ID=:project_id AND r.STATUS IN ('SUCCESS','FAILED','SKIPPED','CANCELLED') AND r.END_DATE < :cutoff AND EXISTS (SELECT 1 FROM AUD_TASK_RUN_LOG tr WHERE tr.PIPELINE_RUN_ID=r.PIPELINE_RUN_ID AND EXISTS (SELECT 1 FROM AUD_BUSINESS_RULES_RUN_LOG br WHERE br.TASK_RUN_ID=tr.TASK_RUN_ID AND br.BUSINESS_RULE_RUN_ID=t.BUSINESS_RULE_RUN_ID)))) AND t.ACTIVE_FLAG='N' AND t.END_DATE < :cutoff
ORDER BY t.BUSINESS_RULE_RESULT_ID LIMIT 10000
)
